import{_ as a,p as e,q as n,Y as s}from"./framework-e1bed10d.js";const i="/my-blog/assets/iShot_2025-12-20_22.43.40-d02cab0f.png",r={},d=s('<h1 id="docker" tabindex="-1"><a class="header-anchor" href="#docker" aria-hidden="true">#</a> Docker</h1><h2 id="docker三要素" tabindex="-1"><a class="header-anchor" href="#docker三要素" aria-hidden="true">#</a> Docker三要素</h2><h3 id="镜像-image" tabindex="-1"><a class="header-anchor" href="#镜像-image" aria-hidden="true">#</a> 镜像 Image</h3><p>镜像是一个只读的模板，可以用来创建容器，一个镜像可以用来创建多个容器，镜像相当于一个文件系统</p><h3 id="容器-container" tabindex="-1"><a class="header-anchor" href="#容器-container" aria-hidden="true">#</a> 容器 Container</h3><p>容器是使用镜像创建的一个虚拟的、隔离的运行环境，用于独立运行一个或者一组应用，应用程序或者服务运行在容器里面。</p><h3 id="仓库-repository" tabindex="-1"><a class="header-anchor" href="#仓库-repository" aria-hidden="true">#</a> 仓库 Repository</h3><p>仓库是存放镜像文件的场所</p><h2 id="docker架构图" tabindex="-1"><a class="header-anchor" href="#docker架构图" aria-hidden="true">#</a> Docker架构图</h2><h3 id="基础架构" tabindex="-1"><a class="header-anchor" href="#基础架构" aria-hidden="true">#</a> 基础架构</h3><p><img src="'+i+`" alt="docker简易架构"></p><p>docker是一个c/s架构的系统，docker守护进程运行在主机上，客户端可以通过socket连接到主机，通过发送命令到docker主机来管理docker资源</p><h3 id="docker相比虚拟机的优势" tabindex="-1"><a class="header-anchor" href="#docker相比虚拟机的优势" aria-hidden="true">#</a> docker相比虚拟机的优势</h3><ol><li>docker有着比虚拟机更少的抽象层，docker不需要实现硬件资源的虚拟化，docker容器中的程序使用的是实际硬件资源</li><li>新建一个docker容器，不需要重新加载一个操作系统内核，而是利用宿主机的内核</li></ol><h2 id="常用命令" tabindex="-1"><a class="header-anchor" href="#常用命令" aria-hidden="true">#</a> 常用命令</h2><h3 id="帮助启动类命令" tabindex="-1"><a class="header-anchor" href="#帮助启动类命令" aria-hidden="true">#</a> 帮助启动类命令</h3><h4 id="启动docker" tabindex="-1"><a class="header-anchor" href="#启动docker" aria-hidden="true">#</a> 启动docker</h4><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>systemctl start <span class="token function">docker</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><h4 id="停止docker" tabindex="-1"><a class="header-anchor" href="#停止docker" aria-hidden="true">#</a> 停止docker</h4><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>systemctl stop <span class="token function">docker</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><h4 id="重启docker" tabindex="-1"><a class="header-anchor" href="#重启docker" aria-hidden="true">#</a> 重启docker</h4><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>systemctl restart <span class="token function">docker</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><h4 id="查看docker状态" tabindex="-1"><a class="header-anchor" href="#查看docker状态" aria-hidden="true">#</a> 查看docker状态</h4><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>systemctl status <span class="token function">docker</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><h4 id="开机启动docker" tabindex="-1"><a class="header-anchor" href="#开机启动docker" aria-hidden="true">#</a> 开机启动docker</h4><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>system <span class="token builtin class-name">enable</span> <span class="token function">docker</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><h4 id="查看docker概要信息" tabindex="-1"><a class="header-anchor" href="#查看docker概要信息" aria-hidden="true">#</a> 查看docker概要信息</h4><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token function">docker</span> info
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><h4 id="查看总体帮助文档" tabindex="-1"><a class="header-anchor" href="#查看总体帮助文档" aria-hidden="true">#</a> 查看总体帮助文档</h4><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token function">docker</span> <span class="token parameter variable">--help</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><h4 id="查看单个命令帮助文档" tabindex="-1"><a class="header-anchor" href="#查看单个命令帮助文档" aria-hidden="true">#</a> 查看单个命令帮助文档</h4><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token function">docker</span> 命令 <span class="token parameter variable">--help</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><h3 id="镜像命令" tabindex="-1"><a class="header-anchor" href="#镜像命令" aria-hidden="true">#</a> 镜像命令</h3><h4 id="本地镜像列表" tabindex="-1"><a class="header-anchor" href="#本地镜像列表" aria-hidden="true">#</a> 本地镜像列表</h4><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token function">docker</span> images
<span class="token function">docker</span> images <span class="token parameter variable">-a</span> <span class="token comment"># 显示所有镜像</span>
<span class="token function">docker</span> images <span class="token parameter variable">-q</span> <span class="token comment"># 显示所有镜像ID</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h4 id="搜索镜像" tabindex="-1"><a class="header-anchor" href="#搜索镜像" aria-hidden="true">#</a> 搜索镜像</h4><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token function">docker</span> search 镜像名
<span class="token function">docker</span> search 镜像名 <span class="token parameter variable">-s</span> <span class="token number">5</span> <span class="token comment"># 搜索镜像，并显示5个结果</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><h4 id="拉取镜像" tabindex="-1"><a class="header-anchor" href="#拉取镜像" aria-hidden="true">#</a> 拉取镜像</h4><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token function">docker</span> pull 镜像名
<span class="token function">docker</span> pull 镜像名:标签
<span class="token function">docker</span> pull 镜像名:标签@sha256:镜像ID
<span class="token function">docker</span> pull 镜像名:latest
<span class="token function">docker</span> pull registry.cn-hangzhou.aliyuncs.com/library/nginx:latest
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h4 id="删除镜像" tabindex="-1"><a class="header-anchor" href="#删除镜像" aria-hidden="true">#</a> 删除镜像</h4><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token function">docker</span> rmi 镜像ID<span class="token punctuation">[</span>:标签<span class="token punctuation">]</span>
<span class="token function">docker</span> rmi 镜像名<span class="token punctuation">[</span>:标签<span class="token punctuation">]</span>
<span class="token function">docker</span> rmi <span class="token parameter variable">-f</span> 镜像ID<span class="token punctuation">[</span>:标签<span class="token punctuation">]</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h4 id="查看镜像、容器所占用空间" tabindex="-1"><a class="header-anchor" href="#查看镜像、容器所占用空间" aria-hidden="true">#</a> 查看镜像、容器所占用空间</h4><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token function">docker</span> system <span class="token function">df</span>
<span class="token function">docker</span> system <span class="token function">df</span> <span class="token parameter variable">-v</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="容器命令" tabindex="-1"><a class="header-anchor" href="#容器命令" aria-hidden="true">#</a> 容器命令</h3><h4 id="启动容器" tabindex="-1"><a class="header-anchor" href="#启动容器" aria-hidden="true">#</a> 启动容器</h4><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 创建并运行容器</span>
<span class="token function">docker</span> run <span class="token punctuation">[</span>options<span class="token punctuation">]</span> 镜像名 <span class="token punctuation">[</span>命令<span class="token punctuation">]</span> <span class="token punctuation">[</span>参数<span class="token punctuation">]</span> 

<span class="token comment"># options</span>
<span class="token parameter variable">-d</span> 后台运行容器并返回容器ID，也称启动守护式容器
<span class="token parameter variable">-i</span> 以交互模式运行容器，通常与-t同时使用
<span class="token parameter variable">-t</span> 为容器重新分配一个伪输入终端，通常与-i同时使用
<span class="token parameter variable">-p</span> 小写p，指定端口映射，hostPort:containerPort
<span class="token parameter variable">-P</span> 大写P，随机映射端口
<span class="token parameter variable">--name</span> 容器名
<span class="token parameter variable">--rm</span> 删除容器
<span class="token parameter variable">--network</span><span class="token operator">=</span>bridge 使用默认的网络
<span class="token parameter variable">--network</span><span class="token operator">=</span>host 使用主机网络
<span class="token parameter variable">--network</span><span class="token operator">=</span>自定义网络 使用自定义的网络

<span class="token comment"># 启动已经停止的容器</span>
<span class="token function">docker</span> start 容器ID或容器名

<span class="token comment"># 重启容器</span>
<span class="token function">docker</span> restart 容器ID或容器名
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>docker容器后台运行，必须有一个前台进程，如果容器运行的命令不是一直挂起的命令，就会自动退出，这个是docker的机制</p><p>最佳的解决方案是，将要运行的程序以前台进程的形式运行，常见的就是<strong>命令行模式</strong></p><h4 id="列出容器" tabindex="-1"><a class="header-anchor" href="#列出容器" aria-hidden="true">#</a> 列出容器</h4><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token function">docker</span> <span class="token function">ps</span> <span class="token comment"># 列出正在运行的容器</span>
<span class="token function">docker</span> <span class="token function">ps</span> <span class="token parameter variable">-a</span> <span class="token comment"># 列出所有容器</span>
<span class="token function">docker</span> <span class="token function">ps</span> <span class="token parameter variable">-q</span> <span class="token comment"># 列出所有容器ID</span>
<span class="token function">docker</span> <span class="token function">ps</span> <span class="token parameter variable">-aq</span> <span class="token comment"># 列出所有容器ID并去重</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h4 id="退出容器" tabindex="-1"><a class="header-anchor" href="#退出容器" aria-hidden="true">#</a> 退出容器</h4><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token builtin class-name">exit</span> <span class="token comment"># 退出容器 容器会自动停止</span>
ctrl + p + q <span class="token comment"># 退出容器 容器不会自动停止</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><h4 id="停止容器" tabindex="-1"><a class="header-anchor" href="#停止容器" aria-hidden="true">#</a> 停止容器</h4><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 停止容器</span>
<span class="token function">docker</span> stop 容器ID或容器名

<span class="token comment"># 强制停止容器</span>
<span class="token function">docker</span> <span class="token function">kill</span> 容器ID或容器名
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h4 id="删除容器" tabindex="-1"><a class="header-anchor" href="#删除容器" aria-hidden="true">#</a> 删除容器</h4><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 删除已停止的容器</span>
<span class="token function">docker</span> <span class="token function">rm</span> 容器ID或容器名

<span class="token comment"># 强制删除容器</span>
<span class="token function">docker</span> <span class="token function">rm</span> <span class="token parameter variable">-f</span> 容器ID或容器名
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h4 id="查看容器日志" tabindex="-1"><a class="header-anchor" href="#查看容器日志" aria-hidden="true">#</a> 查看容器日志</h4><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token function">docker</span> logs 容器ID或容器名
<span class="token function">docker</span> logs <span class="token parameter variable">-f</span> 容器ID或容器名 <span class="token comment"># 持续查看容器日志</span>
<span class="token function">docker</span> logs <span class="token parameter variable">-n</span> <span class="token number">10</span> 容器ID或容器名 <span class="token comment"># 查看最后10行日志</span>
<span class="token function">docker</span> logs <span class="token parameter variable">--since</span> 1h 容器ID或容器名 <span class="token comment"># 查看1小时内的日志</span>
<span class="token function">docker</span> logs <span class="token parameter variable">--tail</span> <span class="token number">10</span> 容器ID或容器名 <span class="token comment"># 查看最后10行日志</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h4 id="容器信息" tabindex="-1"><a class="header-anchor" href="#容器信息" aria-hidden="true">#</a> 容器信息</h4><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token function">docker</span> inspect 容器ID或容器名
<span class="token function">docker</span> <span class="token function">top</span> 容器ID或容器名
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><h4 id="进入容器" tabindex="-1"><a class="header-anchor" href="#进入容器" aria-hidden="true">#</a> 进入容器</h4><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token function">docker</span> <span class="token builtin class-name">exec</span> <span class="token parameter variable">-it</span> 容器ID或容器名 <span class="token function">bash</span>
<span class="token function">docker</span> <span class="token builtin class-name">exec</span> <span class="token parameter variable">-it</span> 容器ID或容器名 /bin/bash
<span class="token function">docker</span> <span class="token builtin class-name">exec</span> <span class="token parameter variable">-it</span> 容器ID或容器名 /bin/sh
<span class="token function">docker</span> <span class="token builtin class-name">exec</span> <span class="token parameter variable">-it</span> 容器ID或容器名 /bin/sh <span class="token parameter variable">-c</span> <span class="token string">&quot;ls -l&quot;</span>

<span class="token function">docker</span> attach 容器ID或容器名
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>attach命令和exec命令一样，attach不会创建一个新的进程，使用exit退出容器终端会导致容器停止；使用exec命令可以创建一个新的进程，使用exit退出容器终端不会导致容器停止</p><h4 id="容器文件导出到宿主机" tabindex="-1"><a class="header-anchor" href="#容器文件导出到宿主机" aria-hidden="true">#</a> 容器文件导出到宿主机</h4><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token function">docker</span> <span class="token function">cp</span> 容器ID或容器名:/文件路径 宿主机路径
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><h4 id="容器导入导出" tabindex="-1"><a class="header-anchor" href="#容器导入导出" aria-hidden="true">#</a> 容器导入导出</h4><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 导出容器内容为一个tar包</span>
<span class="token function">docker</span> <span class="token builtin class-name">export</span> 容器ID或容器名 <span class="token operator">&gt;</span> 文件名.tar

<span class="token comment"># 从tar包中的内容创建一个新的镜像</span>
<span class="token function">docker</span> <span class="token function">import</span> 文件名.tar 镜像名:标签
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h4 id="提交容器为镜像" tabindex="-1"><a class="header-anchor" href="#提交容器为镜像" aria-hidden="true">#</a> 提交容器为镜像</h4><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token function">docker</span> commit 容器ID或容器名 镜像名:标签
<span class="token function">docker</span> commit <span class="token parameter variable">-a</span> <span class="token string">&quot;作者&quot;</span> <span class="token parameter variable">-m</span> <span class="token string">&quot;镜像描述&quot;</span> 容器ID或容器名 镜像名:标签
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="镜像" tabindex="-1"><a class="header-anchor" href="#镜像" aria-hidden="true">#</a> 镜像</h2><h3 id="什么是镜像" tabindex="-1"><a class="header-anchor" href="#什么是镜像" aria-hidden="true">#</a> 什么是镜像</h3><p>镜像是一种轻量级、可执行的独立软件包，它包含运行某个软件所需的所有内容，我们把应用程序和配置依赖打包好形成一个可交付的运行环境(包括代码、运行时需要的库、环境变量和配置文件等)，这个打包好的运行环境就是image镜像文件</p><h3 id="镜像分层" tabindex="-1"><a class="header-anchor" href="#镜像分层" aria-hidden="true">#</a> 镜像分层</h3><p>镜像分层是指一层一层的文件系统，分层的好处是方便复用和迁移</p><p>镜像都是可读的，容器启动时，会在容器的顶部加载一个新的可写层，这一层通常被称为“容器层”，容器层以下的都称为镜像层</p><p>镜像层和容器层是隔离的，容器层上的修改不会影响镜像层，镜像层上的修改也不会影响容器层</p><h3 id="联合文件系统" tabindex="-1"><a class="header-anchor" href="#联合文件系统" aria-hidden="true">#</a> 联合文件系统</h3><p>Union文件系统（UnionFS）是一种分层、轻量级并且高性能的文件系统，它支持对文件系统的修改作一次提交来一层层的叠加，同时可以将不同目录桂载到同一个虚拟文件系统 下(unite several directories into a single virtual filesystem)。 Union 文件系统是 Docker 镜像的基础。镜像可以通过分层来进行维承，基于基础镜像（没有父镜像），可以制作各种具体的应用镜像。</p><p>特性：一次同时加载多个文件系统，但从外面看起来，只能看到一个文件系统，联合加载会把各层文件系统叠加起来，这样最终的文件系统会包含所有底层的文件和目录</p><h3 id="镜像加载原理" tabindex="-1"><a class="header-anchor" href="#镜像加载原理" aria-hidden="true">#</a> 镜像加载原理</h3><p>docker的镜像实际上由一层一层的文件系统组成，这种层级的文件系统UnionFs</p><p>bootfs(bootTile system)主要包含bootloader和kernel, bootloader主要是引导加载kernel, Linux刚启动时会加载bootfs文件系统，在Docker镜像的最底层是引导文件系统bootfs。这一层与我们典型的Linux/Unix系统是一样的，包含boot加载器和内核。当boot加载完成之后整个内核就都在内存中了，此时内存的使用权己由bootfs转交给内核，此时系统也会卸载bootfs。</p><p>rootfs (root file system)，在bootfs之上。包含的就是典型 Linux 系统中的 /dev, /proc, /bin, /etc 等标准目录和文件。rootfs就是各种不同的操作系统发行版，比如Ubuntu,Centos等等。</p><h2 id="容器卷" tabindex="-1"><a class="header-anchor" href="#容器卷" aria-hidden="true">#</a> 容器卷</h2><p>卷是文件或者目录，存在于一个或者多个容器中，用于持久存储和共享数据</p><p>容器卷独立于容器的生命周期，不会在容器删除时删除容器卷</p><h3 id="运行一个带有容器卷的容器" tabindex="-1"><a class="header-anchor" href="#运行一个带有容器卷的容器" aria-hidden="true">#</a> 运行一个带有容器卷的容器</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token function">docker</span> run <span class="token parameter variable">-d</span> <span class="token parameter variable">-privileged</span> <span class="token parameter variable">-v</span> 主机目录path:容器目录path 镜像名:标签 命令
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><h3 id="容器卷的继承" tabindex="-1"><a class="header-anchor" href="#容器卷的继承" aria-hidden="true">#</a> 容器卷的继承</h3><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>docker run -d -privileged --volumes-from 容器ID或容器名称 镜像名:标签 命令
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><h2 id="dockerfile" tabindex="-1"><a class="header-anchor" href="#dockerfile" aria-hidden="true">#</a> Dockerfile</h2><p>Dockerfile是用来构建Docker镜像的文本文件，是由一条条构建镜像所需的指令和参数构成的脚本</p><h3 id="文件编写规则" tabindex="-1"><a class="header-anchor" href="#文件编写规则" aria-hidden="true">#</a> 文件编写规则</h3><ol><li>文件名必须为Dockerfile</li><li>每条保留字指令都必须为大写字母且后面至少要跟随一个参数</li><li>指令从上至下，顺序执行</li><li>注释使用#标识</li><li>每条指令都会创建一个新的镜像层并对镜像进行提交</li></ol><h3 id="执行流程" tabindex="-1"><a class="header-anchor" href="#执行流程" aria-hidden="true">#</a> 执行流程</h3><ol><li>docker从基础镜像创建一个容器</li><li>执行一条指令对容器进行修改</li><li>执行类似commit的操作，提交一个新的镜像层</li><li>基于新的镜像，创建一个新的容器</li><li>执行下一条指令，重复上述布置，直到最后一条指令</li></ol><h3 id="常用指令" tabindex="-1"><a class="header-anchor" href="#常用指令" aria-hidden="true">#</a> 常用指令</h3><h4 id="from" tabindex="-1"><a class="header-anchor" href="#from" aria-hidden="true">#</a> FROM</h4><p>指定基础镜像，第一项必须是FROM，FROM 镜像名:标签</p><h4 id="maintainer" tabindex="-1"><a class="header-anchor" href="#maintainer" aria-hidden="true">#</a> MAINTAINER</h4><p>指定镜像的作者和邮箱地址</p><h4 id="run" tabindex="-1"><a class="header-anchor" href="#run" aria-hidden="true">#</a> RUN</h4><p>在build时，执行一条命令，RUN &lt;命令行命令&gt;，可以是shell和exec格式</p><h4 id="expose" tabindex="-1"><a class="header-anchor" href="#expose" aria-hidden="true">#</a> EXPOSE</h4><p>指定容器向外暴露的端口号，EXPOSE 端口号</p><h4 id="workdir" tabindex="-1"><a class="header-anchor" href="#workdir" aria-hidden="true">#</a> WORKDIR</h4><p>指定容器工作目录，WORKDIR 目录，指定在创建容器后，终端默认登录进来的工作目录</p><h4 id="env" tabindex="-1"><a class="header-anchor" href="#env" aria-hidden="true">#</a> ENV</h4><p>用来在构建镜像过程中设置环境变量，ENV 变量名 变量值</p><h4 id="volume" tabindex="-1"><a class="header-anchor" href="#volume" aria-hidden="true">#</a> VOLUME</h4><p>创建一个容器卷，VOLUME 目录</p><h4 id="add" tabindex="-1"><a class="header-anchor" href="#add" aria-hidden="true">#</a> ADD</h4><p>添加文件或者目录到镜像中，ADD &lt;源文件&gt; &lt;目标文件&gt;，会自动处理url和解压tar压缩包</p><h4 id="copy" tabindex="-1"><a class="header-anchor" href="#copy" aria-hidden="true">#</a> COPY</h4><p>添加文件或者目录到镜像中，COPY &lt;源文件&gt; &lt;目标文件&gt;，不会自动处理url和解压tar压缩包</p><h4 id="cmd" tabindex="-1"><a class="header-anchor" href="#cmd" aria-hidden="true">#</a> CMD</h4><p>指定容器启动时执行的命令，CMD [命令，参数1，参数2，...]，dockerfile中可以有多个cmd命令，但是只有最后一个会生效，在使用docker run时，如果指定了cmd命令，那么dockerfile中的cmd命令会被覆盖</p><h4 id="entrypoint" tabindex="-1"><a class="header-anchor" href="#entrypoint" aria-hidden="true">#</a> ENTRYPOINT</h4><p>指定容器启动时执行的命令，ENTRYPOINT [命令，参数1，参数2，...]，ENTRYPOINT命令会覆盖CMD命令，但是ENTRYPOINT命令不能被docker run命令所覆盖</p><p>当指定ENTRYPOINT命令时，CMD命令的含义就发生了变化，CMD命令的参数会被追加到ENTRYPOINT命令的参数中，最终的命令行参数为ENTRYPOINT命令的参数+CMD命令的参数</p><h2 id="docker网络" tabindex="-1"><a class="header-anchor" href="#docker网络" aria-hidden="true">#</a> Docker网络</h2><p>Docker网络是Docker容器之间进行通信的基础，Docker默认使用bridge网络模式，bridge网络模式下，Docker会创建一个docker0网桥，并把所有容器的网卡都加入到docker0网桥中，docker0网桥会监听所有端口，并把接收到的数据包转发给对应的容器</p><h3 id="网络模式" tabindex="-1"><a class="header-anchor" href="#网络模式" aria-hidden="true">#</a> 网络模式</h3><h4 id="_1-bridge模式" tabindex="-1"><a class="header-anchor" href="#_1-bridge模式" aria-hidden="true">#</a> 1. bridge模式</h4><p>创建一个docker0网桥，并把所有容器的网卡都加入到docker0网桥中，docker0网桥会监听所有端口，并把接收到的数据包转发给对应的容器，每个容器有一个自己的IP地址和端口</p><h4 id="_2-host模式" tabindex="-1"><a class="header-anchor" href="#_2-host模式" aria-hidden="true">#</a> 2. host模式</h4><p>容器的网卡会与宿主机的网卡进行绑定，容器的端口会与宿主机的端口进行绑定</p><p>容器启动后，相当于在宿主机上启动了一个进程，容器的服务直接通过宿主机的ip和端口进行方案</p><h4 id="_3-none模式" tabindex="-1"><a class="header-anchor" href="#_3-none模式" aria-hidden="true">#</a> 3. none模式</h4><p>容器的网卡不会与宿主机的网卡进行绑定，容器的端口不会与宿主机的端口进行绑定</p><h4 id="_4-container模式" tabindex="-1"><a class="header-anchor" href="#_4-container模式" aria-hidden="true">#</a> 4. container模式</h4><p>创建一个容器，并指定容器的网卡与 another_container 容器的网卡进行绑定</p><h3 id="网络操作" tabindex="-1"><a class="header-anchor" href="#网络操作" aria-hidden="true">#</a> 网络操作</h3><h4 id="创建一个自定义网络" tabindex="-1"><a class="header-anchor" href="#创建一个自定义网络" aria-hidden="true">#</a> 创建一个自定义网络</h4><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token function">docker</span> network create <span class="token parameter variable">-d</span> bridge 网络名称
<span class="token function">docker</span> network create <span class="token parameter variable">-d</span> bridge <span class="token parameter variable">--subnet</span><span class="token operator">=</span><span class="token number">172.18</span>.0.0/16 <span class="token parameter variable">--gateway</span><span class="token operator">=</span><span class="token number">172.18</span>.0.1 网络名称
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><h4 id="查看网络" tabindex="-1"><a class="header-anchor" href="#查看网络" aria-hidden="true">#</a> 查看网络</h4><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token function">docker</span> network <span class="token function">ls</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><h4 id="删除网络" tabindex="-1"><a class="header-anchor" href="#删除网络" aria-hidden="true">#</a> 删除网络</h4><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token function">docker</span> network <span class="token function">rm</span> 网络名称
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><h2 id="docker容器编排" tabindex="-1"><a class="header-anchor" href="#docker容器编排" aria-hidden="true">#</a> Docker容器编排</h2><p>Docker容器编排，是多个容器组成的一个应用，Docker容器编排工具有Docker Compose和Kubernetes</p><p>docker建议我们每一个容器中只运行一个服务，如果同时部署多个服务，就需要为每个服务单独写dockerfile来构建镜像，docker官方提供了docker-compose来进行多服务部署</p><p>docker-compose允许用户通过一个单独的docker-compose.yml文件来定义一组相关联的应用容器组成一个应用</p><h3 id="常用命令-1" tabindex="-1"><a class="header-anchor" href="#常用命令-1" aria-hidden="true">#</a> 常用命令</h3><ol><li>docker-compose up 启动所有服务</li><li>docker-compose up -d 启动所有服务并后台运行</li><li>docker-compose down 停止所有服务并删除容器、网络、卷</li><li>docker-compose stop 停止所有服务</li><li>docker-compose start 启动所有服务</li><li>docker-compose restart 重启所有服务</li><li>docker-compose ps 列出所有服务</li><li>docker-compose exec yum文件里的服务id 进入容器实例内部</li><li>docker-compose logs yum文件里的服务id 查看指定容器的输出日志</li><li>docker-compose config 检查配置</li><li>docker-compose config -q 检查配置，有问题则输出</li></ol>`,145),c=[d];function l(o,t){return e(),n("div",null,c)}const h=a(r,[["render",l],["__file","docker-base.html.vue"]]);export{h as default};
